#!/usr/bin/env python3
# Pure-python AES (encryption only) + CFB mode, for candidate testing.
sbox = []
def _init():
    p = q = 1
    s = [0]*256
    while True:
        p = p ^ ((p<<1)&0xff) ^ (0x1b if p&0x80 else 0)
        q ^= q<<1; q ^= q<<2; q ^= q<<4; q &= 0xff
        if q&0x80: q ^= 0x09
        q &= 0xff
        xformed = q ^ ((q<<1)|(q>>7)) ^ ((q<<2)|(q>>6)) ^ ((q<<3)|(q>>5)) ^ ((q<<4)|(q>>4))
        s[p] = (xformed ^ 0x63) & 0xff
        if p == 1: break
    s[0] = 0x63
    return s
SBOX = _init()
RCON = [0x01,0x02,0x04,0x08,0x10,0x20,0x40,0x80,0x1b,0x36,0x6c,0xd8,0xab,0x4d]

def key_expand(key):
    Nk = len(key)//4
    Nr = Nk + 6
    w = [list(key[4*i:4*i+4]) for i in range(Nk)]
    for i in range(Nk, 4*(Nr+1)):
        t = list(w[i-1])
        if i % Nk == 0:
            t = [SBOX[t[1]]^RCON[i//Nk-1], SBOX[t[2]], SBOX[t[3]], SBOX[t[0]]]
        elif Nk > 6 and i % Nk == 4:
            t = [SBOX[b] for b in t]
        w.append([w[i-Nk][j]^t[j] for j in range(4)])
    return w, Nr

def xtime(a): return ((a<<1)&0xff) ^ (0x1b if a&0x80 else 0)
def mul(a,b):
    r=0
    while b:
        if b&1: r^=a
        a=xtime(a); b>>=1
    return r

def aes_encrypt_block(block, w, Nr):
    s = [[block[4*c+r] for c in range(4)] for r in range(4)]
    def add_rk(rd):
        for c in range(4):
            for r in range(4):
                s[r][c] ^= w[4*rd+c][r]
    add_rk(0)
    for rd in range(1, Nr+1):
        for r in range(4):
            for c in range(4):
                s[r][c] = SBOX[s[r][c]]
        for r in range(1,4):
            s[r] = s[r][r:]+s[r][:r]
        if rd < Nr:
            for c in range(4):
                col=[s[0][c],s[1][c],s[2][c],s[3][c]]
                s[0][c]=mul(col[0],2)^mul(col[1],3)^col[2]^col[3]
                s[1][c]=col[0]^mul(col[1],2)^mul(col[2],3)^col[3]
                s[2][c]=col[0]^col[1]^mul(col[2],2)^mul(col[3],3)
                s[3][c]=mul(col[0],3)^col[1]^col[2]^mul(col[3],2)
        add_rk(rd)
    return bytes(s[r][c] for c in range(4) for r in range(4))

def aes_cfb_encrypt(key, iv, pt):
    w, Nr = key_expand(key)
    out = b''
    prev = iv
    for i in range(0, len(pt), 16):
        ks = aes_encrypt_block(prev, w, Nr)
        blk = pt[i:i+16]
        ct = bytes(a^b for a,b in zip(blk, ks))
        out += ct
        prev = ct if len(ct)==16 else None
        if len(ct) < 16: break
    return out

if __name__ == '__main__':
    # FIPS-197 test vectors
    w,Nr = key_expand(bytes(16))
    assert aes_encrypt_block(bytes(16), w, Nr).hex() == '66e94bd4ef8a2c3b884cfa59ca342b2e'
    w,Nr = key_expand(bytes(32))
    assert aes_encrypt_block(bytes(16), w, Nr).hex() == 'dc95c078a2408989ad48a21492842087'
    print('AES self-test OK')
